import{_ as a,a as t,o as r,a4 as i}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"EU Withdrawal","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/sales/eu-withdrawal/index.md","filePath":"api/graphql-api/admin/sales/eu-withdrawal/index.md","lastUpdated":1784902076000}'),d={name:"api/graphql-api/admin/sales/eu-withdrawal/index.md"};function n(o,e,s,l,c,h){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="eu-withdrawal" tabindex="-1">EU Withdrawal <a class="header-anchor" href="#eu-withdrawal" aria-label="Permalink to &quot;EU Withdrawal&quot;">​</a></h1><p>The EU Withdrawal menu is the store-wide queue of every <strong>right-of-withdrawal declaration</strong> a customer has filed against an order — the EU consumer&#39;s statutory right to withdraw from a distance purchase. It mirrors the admin <strong>Sales → EU Withdrawal</strong> screen: browse declarations, open one for its full evidence timeline, and act on it (decline, mark refunded, or resend the confirmation email).</p><h2 id="when-a-row-appears-here" tabindex="-1">When a row appears here <a class="header-anchor" href="#when-a-row-appears-here" aria-label="Permalink to &quot;When a row appears here&quot;">​</a></h2><p>A row exists once a customer has <strong>submitted a withdrawal declaration</strong> for an order from the storefront. Each declaration captures who filed it (the customer or a guest), against which order, in which channel and locale, the free-text reason, and the moment it was received.</p><h2 id="the-evidence-timeline" tabindex="-1">The evidence timeline <a class="header-anchor" href="#the-evidence-timeline" aria-label="Permalink to &quot;The evidence timeline&quot;">​</a></h2><p>Every declaration keeps a durable, ordered record of what happened and when — this is the compliance evidence a merchant must retain:</p><ol><li><strong>Received</strong> — the customer submits the declaration (<code>receivedAt</code>, <code>status: received</code>).</li><li><strong>Confirmation email</strong> — the storefront sends a durable-medium acknowledgement to the customer (<code>confirmationSentAt</code>). If sending failed, the reason is recorded in <code>confirmationError</code>; <code>finalConfirmationSentAt</code> records a later re-send.</li><li><strong>Outcome</strong> — the merchant either: <ul><li><strong>Declines</strong> the declaration when the purchase is exempt from withdrawal (<code>status: declined</code>, <code>declinedAt</code>, <code>declinedReason</code>, <code>declinedByUserId</code>, <code>declinedByName</code>), or</li><li><strong>Marks it refunded</strong> once the money has been returned out-of-band (<code>status: refunded</code>, <code>refundedAt</code>, <code>refundedByUserId</code>, <code>refundedByName</code>, <code>refundNote</code>).</li></ul></li></ol><p>The two outcomes are mutually exclusive: <strong>declining clears any prior refund metadata, and marking refunded clears any prior decline metadata</strong>, so a declaration always reflects a single, current outcome.</p><p><strong>Resend confirmation</strong> re-sends the durable-medium acknowledgement email in the declaration&#39;s locale and refreshes <code>confirmationSentAt</code> — used when the original email bounced or the customer asks for another copy.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/sales/eu-withdrawal/queries/list-eu-withdrawals.html">List declarations</a></td><td><code>adminEuWithdrawals</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/eu-withdrawal/queries/view-eu-withdrawal.html">Get a single declaration</a></td><td><code>adminEuWithdrawal(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/eu-withdrawal/mutations/decline.html">Decline a declaration</a></td><td><code>declineAdminEuWithdrawal</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/eu-withdrawal/mutations/mark-refunded.html">Mark refunded</a></td><td><code>markRefundedAdminEuWithdrawal</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/eu-withdrawal/mutations/resend-confirmation.html">Resend confirmation</a></td><td><code>resendConfirmationAdminEuWithdrawal</code> mutation</td></tr></tbody></table><p>All EU Withdrawal operations run against the admin GraphQL endpoint <code>POST /api/admin/graphql</code> and require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>. The list and view queries require the <code>sales.eu_withdrawals</code> permission; each mutation requires its own permission (noted on its page).</p>',12)]))}const p=a(d,[["render",n]]);export{u as __pageData,p as default};
